CREATE TABLE IF NOT EXISTS companies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, legal_name TEXT, website TEXT, phone TEXT, email TEXT, billing_email TEXT, status TEXT NOT NULL DEFAULT 'prospect', industry TEXT, address_line1 TEXT, address_line2 TEXT, city TEXT, county TEXT, postcode TEXT, country TEXT, owner_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, job_title TEXT, email TEXT, phone TEXT, mobile TEXT, is_primary BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS activities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id) ON DELETE CASCADE, contact_id UUID REFERENCES contacts(id) ON DELETE SET NULL, opportunity_id UUID, project_id UUID, ticket_id UUID, invoice_id UUID, activity_type TEXT NOT NULL, title TEXT NOT NULL, body TEXT, created_by_user_id UUID REFERENCES users(id), occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
